import{_ as a,I as i,g as t,j as n}from"./chunks/framework.YqoK2ckR.js";const c=JSON.parse('{"title":"ROS2 安装教程","description":"","frontmatter":{},"headers":[],"relativePath":"notes/ROS2/01-安装.md","filePath":"notes/ROS2/01-安装.md"}'),e={name:"notes/ROS2/01-安装.md"};function h(l,s,p,d,k,r){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="ros2-安装教程" tabindex="-1">ROS2 安装教程 <a class="header-anchor" href="#ros2-安装教程" aria-label="Permalink to &quot;ROS2 安装教程&quot;">​</a></h1><p>一条命令在 Ubuntu 上装好 ROS2（国内镜像，自动匹配版本）。点击链接下载脚本：<a href="/download.sh" target="_self" download="">download.sh</a></p><table tabindex="0"><thead><tr><th>Ubuntu 版本</th><th>自动安装的 ROS2</th></tr></thead><tbody><tr><td>22.04</td><td>Humble</td></tr><tr><td>24.04</td><td>Jazzy</td></tr></tbody></table><hr><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>我没有尝试不挂梯子运行命令，我当时是开着梯子安装的，不过既然你都搞ROS了，就默认你已经拥有了稳定高速的梯子</p><p>我们先在根目录新建专门的文件夹，再把脚本复制进去，再cd到那个目录执行脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ros2_install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ros2_install/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 把脚本拷到这个目录</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ros2_install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # 正式运行安装脚本，不要用 sudo 运行脚本本身</span></span></code></pre></div><p>安装过程中会要求输入 sudo 密码，属正常现象。</p><p><strong>运行完上面5个命令，网络链接好的话，不出意外的话已经安装成功了</strong></p><p><strong>可选参数</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> base</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 最小安装，不含 RViz（体积更小）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 只预览，不实际安装</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 查看全部选项</span></span></code></pre></div><hr><h2 id="安装后必做-加载环境" tabindex="-1">安装后必做：加载环境 <a class="header-anchor" href="#安装后必做-加载环境" aria-label="Permalink to &quot;安装后必做：加载环境&quot;">​</a></h2><p>脚本会把 ROS2 写入 <code>~/.bashrc</code>，但<strong>当前终端不会自动生效</strong>。</p><p>任选其一：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 让当前终端立刻可用</span></span></code></pre></div><p>或<strong>重新打开一个终端</strong>。</p><p>未执行上述步骤时，会出现 <code>ros2：未找到命令</code>。</p><p>验证是否成功：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 检查环境（不要用 ros2 --version，该命令不存在）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $ROS_DISTRO            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 应显示 humble 或 jazzy</span></span></code></pre></div><hr><h2 id="验证是否成功" tabindex="-1">验证是否成功 <a class="header-anchor" href="#验证是否成功" aria-label="Permalink to &quot;验证是否成功&quot;">​</a></h2><p><strong>Talker / Listener</strong>（开两个终端，都要先 <code>source ~/.bashrc</code>）</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo_nodes_cpp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> talker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 B</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo_nodes_py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> listener</span></span></code></pre></div><p>看到不断打印 <code>Hello World</code> 即成功。</p><p><strong>小海龟</strong>（desktop 版自带）</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turtlesim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turtlesim_node</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 B（用方向键控制）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turtlesim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turtle_teleop_key</span></span></code></pre></div><hr><h2 id="磁盘空间" tabindex="-1">磁盘空间 <a class="header-anchor" href="#磁盘空间" aria-label="Permalink to &quot;磁盘空间&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>建议剩余空间</th></tr></thead><tbody><tr><td>仅安装 + 试用</td><td>20 GB</td></tr><tr><td>日常开发编译</td><td>50 GB 以上</td></tr></tbody></table><p><code>colcon build</code> 产生的 <code>build/</code> 目录很大，是爆盘主因，不是 <code>/opt/ros</code> 本身！</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="ros2-未找到命令" tabindex="-1"><code>ros2：未找到命令</code> <a class="header-anchor" href="#ros2-未找到命令" aria-label="Permalink to &quot;\`ros2：未找到命令\`&quot;">​</a></h3><p>先执行 <code>source ~/.bashrc</code>，或新开终端。每次新开终端一般会自动加载。</p><h3 id="paraview-与-rviz-冲突" tabindex="-1">ParaView 与 RViz 冲突 <a class="header-anchor" href="#paraview-与-rviz-冲突" aria-label="Permalink to &quot;ParaView 与 RViz 冲突&quot;">​</a></h3><p>报错含 <code>python3-paraview : Conflicts: python3-vtk9</code> 时，Ubuntu 24.04 的 ParaView 5.x 与 ROS2 desktop 不能共存。</p><p><strong>做法</strong>：卸载 ParaView 后再装 ROS2；等官方 ParaView 6.0（预计 Ubuntu 26.04+）再装回，届时可与 RViz 共存。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paraview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3-paraview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paraview-doc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download.sh</span></span></code></pre></div><p>若必须保留 ParaView：<code>bash download.sh --type base</code></p><h3 id="locale-报错" tabindex="-1">locale 报错 <a class="header-anchor" href="#locale-报错" aria-label="Permalink to &quot;locale 报错&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locales</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locale-gen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> en_US</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> en_US.UTF-8</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-locale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LC_ALL=en_US.UTF-8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LANG=en_US.UTF-8</span></span></code></pre></div><h3 id="rosdep-apt-失败" tabindex="-1">rosdep / apt 失败 <a class="header-anchor" href="#rosdep-apt-失败" aria-label="Permalink to &quot;rosdep / apt 失败&quot;">​</a></h3><p>查看日志：<code>cat ~/ros2_install/install.log</code><br> 脚本已配置清华 TUNA 镜像；重复运行脚本是安全的（已装部分会自动跳过）。</p><hr>`,46)])])}const F=a(e,[["render",h]]);export{c as __pageData,F as default};
